 const opts=(chart.data||[]).map(a=>'<option value="'+escapeHtml(a.account_code)+'">'+escapeHtml(a.account_code)+' · '+escapeHtml(a.account_name)+' ('+escapeHtml(a.account_type)+')</option>').join('');
 const host=el('adJournalArea');
 host.innerHTML=(perm.data?'<form class="panel" id="adManualJournalForm"><div class="body"><div class="form"><label>জার্নালের তারিখ<input name="date" type="date" value="'+dhaka()+'" required></label><label>জার্নালের বিবরণ<input name="description" maxlength="300" required></label></div><h3>ডেবিট / ক্রেডিট লাইন (কমপক্ষে ২টি)</h3><div class="tablewrap"><table><thead><tr><th>হিসাব</th><th>লাইন বিবরণ</th><th>ডেবিট</th><th>ক্রেডিট</th></tr></thead><tbody>'+[1,2,3,4].map(i=>'<tr><td><select name="account_'+i+'"><option value="">হিসাব নির্বাচন</option>'+opts+'</select></td><td><input name="description_'+i+'" maxlength="180" placeholder="বিবরণ"></td><td><input name="debit_'+i+'" type="number" min="0" step=".01" value="0"></td><td><input name="credit_'+i+'" type="number" min="0" step=".01" value="0"></td></tr>').join('')+'</tbody></table></div><div class="note">মোট ডেবিট ও মোট ক্রেডিট সমান হতে হবে। জমা দেওয়া জার্নাল অনুমোদনের অপেক্ষায় থাকবে; অনুমোদন ছাড়া ব্যালান্স শিটে পোস্ট হবে না。</div><p><button class="action green">জার্নাল অনুমোদনের জন্য জমা দিন</button></p></div></form>':'<div class="note">ম্যানুয়াল জার্নাল তৈরি করার অনুমতি নেই।')+'<section class="panel"><div class="head"><h2>সাম্প্রতিক জার্নাল এন্ট্রি</h2></div><div class="body tablewrap"><table><thead><tr><th>জার্নাল নম্বর</th><th>তারিখ</th><th>বিবরণ</th><th>উৎস</th><th>অবস্থা</th><th>সংশোধন</th></tr></thead><tbody id="adJournalRows">'+(entries.data||[]).map(x=>'<tr><td>JRN-'+fmt(x.journal_no)+'</td><td>'+escapeHtml(x.journal_date)+'</td><td>'+escapeHtml(x.description||'—')+'</td><td>'+escapeHtml(x.source_type)+'</td><td>'+escapeHtml(x.status)+'</td><td>'+(canReverse&&x.status==='posted'&&x.source_type!=='adjustment'&&x.created_by!==user?.id?'<button class="action light" data-reverse-journal="'+x.id+'">রিভার্স / সংশোধন</button>':'—')+'</td></tr>').join('')+'</tbody></table></div></section>';
