 const rows=[...groups.values()],months=[...monthly.values()].sort((a,b)=>a.month.localeCompare(b.month)),fundRows=[...funds.values()].sort((a,b)=>a.fund.localeCompare(b.fund)),income=data.filter(x=>x.entry_type==='income').reduce((n,x)=>n+Number(x.amount||0),0),expense=data.filter(x=>x.entry_type==='expense').reduce((n,x)=>n+Number(x.amount||0),0);
