function memberForm(){
 const host=el('adChandaContent')||el('adPage'),existing=el('adMemberFormPanel');if(existing){existing.scrollIntoView({behavior:'smooth',block:'center'});return}
 const baseMonth=el('adMonth')?.value||today().slice(0,7),[yy,mm]=baseMonth.split('-').map(Number),monthKeys=[];
 for(let i=23;i>=0;i--){const d=new Date(yy,mm-1-i,1);monthKeys.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01')}
 const monthLabel=new Intl.DateTimeFormat('bn-BD',{month:'long',year:'numeric',timeZone:'Asia/Dhaka'});
 const monthOptions=monthKeys.map(key=>'<label style="display:flex;gap:8px;align-items:center;padding:7px 9px;border:1px solid #dbe5df;border-radius:8px"><input type="checkbox" name="first_months" value="'+key+'" '+(key===baseMonth+'-01'?'checked':'')+'><span>'+monthLabel.format(new Date(key+'T12:00:00'))+'</span></label>').join('');
 host.insertAdjacentHTML('afterbegin','<section class="panel" id="adMemberFormPanel"><div class="head"><h2>নতুন চাঁদাদাতা ও প্রথম চাঁদা জমা</h2><button type="button" class="action light" id="adMemberFormClose">ফরম বন্ধ / মুছুন</button></div><div class="body"><form class="form" id="adMemberForm"><label>চাঁদাদাতার নাম<input name="name" required maxlength="140"></label><label>পিতার নাম<input name="father" maxlength="140"></label><label>ঠিকানা<input name="address" maxlength="300"></label><label>মোবাইল নম্বর<input name="phone" maxlength="20"></label><label>মাসিক চাঁদা (টাকা)<input name="amount" type="number" min="1" step=".01" required></label><label>চাঁদা পরিশোধের নির্ধারিত সময়<input value="প্রতি মাসের ১ তারিখের মধ্যে" disabled></label><label class="wide">নোট<textarea name="notes" maxlength="1000"></textarea></label><div class="wide"><h3>প্রথম চাঁদা জমার তথ্য (ঐচ্ছিক)</h3><p>একসঙ্গে ১–২৪ মাস নির্বাচন করুন। কোনো মাস নির্বাচন না করলে শুধু সদস্য সংরক্ষণ হবে।</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:7px;max-height:260px;overflow:auto">__MONTH_OPTIONS__</div></div><label>মোট জমার পরিমাণ (টাকা)<input name="first_amount" type="number" min="0.01" step=".01"></label><label>জমার তারিখ<input name="first_date" type="date" value="__TODAY__"></label><label>জমার মাধ্যম<select name="first_method"><option value="cash">নগদ</option><option value="bank">ব্যাংক</option><option value="bkash">বিকাশ</option><option value="nagad">নগদ (Nagad)</option><option value="other">অন্যান্য</option></select></label><label>যিনি টাকা জমা দিয়েছেন<input name="payer_name" maxlength="140"></label><label>ট্রানজেকশন / রসিদ নম্বর<input name="first_reference" maxlength="120"></label><label class="wide">জমার নোট<input name="first_memo" maxlength="300"></label><div class="wide" id="adFirstPaymentSummary"></div><div class="wide"><button class="action green" type="submit">সদস্য সংরক্ষণ ও চাঁদা জমা</button></div></form></div></section>'.replace('__MONTH_OPTIONS__',monthOptions).replace('__TODAY__',today()));
 el('adMemberFormClose').onclick=()=>el('adMemberFormPanel')?.remove();
 const form=el('adMemberForm'),amountField=form.elements.first_amount,monthlyField=form.elements.amount,summary=el('adFirstPaymentSummary');
 const selectedMonths=()=>[...form.querySelectorAll('[name="first_months"]:checked')];
 const update=()=>{const n=selectedMonths().length,total=n*Number(monthlyField.value||0);if(!amountField.dataset.edited)amountField.value=total?total.toFixed(2):'';summary.textContent=n+' মাস নির্বাচিত · মোট '+money(total)};
 form.querySelectorAll('[name="first_months"]').forEach(x=>x.onchange=()=>{amountField.dataset.edited='';update()});monthlyField.oninput=()=>{amountField.dataset.edited='';update()};amountField.oninput=()=>amountField.dataset.edited='1';update();
 form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type="submit"]');if(submit.disabled)return;submit.disabled=true;submit.textContent='সংরক্ষণ হচ্ছে…';const fd=new FormData(form);try{
  const phone=String(fd.get('phone')||'').trim();if(phone){const {data:duplicates,error}=await supabase.from('chanda_members').select('member_name').eq('phone',phone).eq('status','active').limit(10);if(error)throw error;if(duplicates?.length&&!confirm('এই মোবাইল নম্বরটি আগে '+duplicates.map(x=>x.member_name).join(', ')+' নামের সদস্যের জন্য আছে। একই নম্বর ব্যবহার করবেন?')){submit.disabled=false;submit.textContent='সদস্য সংরক্ষণ ও চাঁদা জমা';return}}
  const {data:created,error}=await supabase.from('chanda_members').insert({institution:'mosque',member_name:String(fd.get('name')).trim(),father_name:String(fd.get('father')||'').trim(),address:String(fd.get('address')||'').trim(),phone,monthly_amount:Number(fd.get('amount')),due_day:1,created_by:user.id,status:'active',contact_consent:false,reminder_channel:'in_app',notes:String(fd.get('notes')||'')}).select('id').single();if(error)throw error;
  const chosen=selectedMonths().map(x=>x.value);if(chosen.length){for(const key of chosen){const {error:de}=await supabase.rpc('ensure_chanda_dues_for_month',{target_month:key});if(de)throw de}
   const {data:rows,error:re}=await supabase.from('chanda_dues').select('id,due_month,amount,paid_amount').eq('member_id',created.id).in('due_month',chosen);if(re)throw re;if((rows||[]).length!==chosen.length)throw new Error('নির্বাচিত মাসগুলোর হিসাব তৈরি হয়নি। সদস্য সংরক্ষিত হয়েছে; পরে মাসিক চাঁদা থেকে জমা নিন।');
   const max=rows.reduce((a,d)=>a+Math.max(0,Number(d.amount)-Number(d.paid_amount)),0),paid=Number(fd.get('first_amount')||0);if(!paid||paid>max)throw new Error('জমার পরিমাণ নির্বাচিত মাসের মোট বকেয়ার মধ্যে দিন। সদস্য সংরক্ষিত হয়েছে; চাঁদা জমা হয়নি।');
   const payer=String(fd.get('payer_name')||'').trim(),memo=[payer?'টাকা জমাদাতা: '+payer:'',String(fd.get('first_memo')||'').trim()].filter(Boolean).join(' | ');
   const {error:pe}=await supabase.rpc('record_chanda_payment_months',{target_dues:rows.map(x=>x.id),p_paid_amount:paid,paid_on:String(fd.get('first_date')||today()),method:String(fd.get('first_method')||'cash'),reference:String(fd.get('first_reference')||''),memo});if(pe)throw pe;alert('সদস্য সংরক্ষিত হয়েছে এবং '+chosen.length+' মাসের '+money(paid)+' চাঁদা জমা হয়েছে।');
  }else alert('চাঁদাদাতা সংরক্ষিত হয়েছে। প্রথম চাঁদা পরে জমা দিতে পারবেন।');
  el('adMemberFormPanel')?.remove();await loadChanda();
 }catch(err){alert(err.message||String(err));submit.disabled=false;submit.textContent='সদস্য সংরক্ষণ ও চাঁদা জমা'}
 };
}

async function paymentHistory(){const {data,error}=await supabase.from('chanda_payments').select('id,member_id,due_id,amount,payment_date,payment_method,reference_no').order('created_at',{ascending:false}).limit(300);if(error){showError(error);return}const ids=[...new Set(data.map(x=>x.member_id))],dueIds=[...new Set(data.map(x=>x.due_id))];let names={},months={};if(ids.length){const r=await supabase.from('chanda_members').select('id,member_name').in('id',ids);if(r.error)throw r.error;(r.data||[]).forEach(x=>names[x.id]=x.member_name)}if(dueIds.length){const r=await supabase.from('chanda_dues').select('id,due_month').in('id',dueIds);if(r.error)throw r.error;(r.data||[]).forEach(x=>months[x.id]=new Intl.DateTimeFormat('bn-BD',{month:'long',year:'numeric',timeZone:'Asia/Dhaka'}).format(new Date(x.due_month+'T12:00:00')))}(el('adChandaContent')||el('adPage')).insertAdjacentHTML('afterbegin','<section class="panel" id="adChandaHistoryPanel"><div class="head"><h2>চাঁদা আদায়ের ইতিহাস</h2><button type="button" class="action light" id="adChandaHistoryClose">বন্ধ করুন</button></div><div class="body tablewrap"><table><thead><tr><th>তারিখ</th><th>চাঁদাদাতা</th><th>যে মাসের জমা</th><th>পরিমাণ</th><th>মাধ্যম</th><th>রেফারেন্স</th><th>রসিদ আইডি</th></tr></thead><tbody>'+data.map(x=>'<tr><td>'+escapeHtml(x.payment_date)+'</td><td>'+escapeHtml(names[x.member_id]||'—')+'</td><td>'+escapeHtml(months[x.due_id]||'—')+'</td><td>'+money(x.amount)+'</td><td>'+escapeHtml(x.payment_method)+'</td><td>'+escapeHtml(x.reference_no||'—')+'</td><td>'+escapeHtml(x.id)+'</td></tr>').join('')+'</tbody></table></div></section>');el('adChandaHistoryClose').onclick=()=>el('adChandaHistoryPanel')?.remove()}
function exportExcel(){const rows=members.map(m=>{const d=dues.find(x=>x.member_id===m.id);return{নাম:m.member_name,ঠিকানা:m.address,মোবাইল:m.phone,মাসিক_চাঁদা:+m.monthly_amount,জমা:+(d?.paid_amount||0),বাকি:Math.max(0,+(d?.amount||m.monthly_amount)-+(d?.paid_amount||0)),অবস্থা:d?.status||'পাওনা তৈরি হয়নি'}});import('https://esm.sh/xlsx@0.18.5').then(X=>{const ws=X.utils.json_to_sheet(rows),wb=X.utils.book_new();X.utils.book_append_sheet(wb,ws,'মাসিক চাঁদা');X.writeFile(wb,'SAKM-61-monthly-chanda.xlsx')}).catch(e=>alert(e.message))}
async function start(){if(!configured||!el('app')||el('app').hidden||el('accountsDashboard'))return;try{const x=await currentProfile();user=x.user;profile=x.profile;if(!user||!profile)return;mount();el('adUser').textContent=(profile.full_name||'Accounts User')+' · '+profile.role;if(el('institution')&&profile.institution!=='both')el('institution').value=profile.institution;await loadModuleVisibility();refreshNav();if(!visibleModules.length){el('adPage').innerHTML='<div class="panel empty">এই প্রতিষ্ঠানের Accounts মডিউলে আপনার অনুমতি নেই।</div>';return}const first=visibleModules.includes(0)?0:visibleModules[0];openModule(first)}catch(e){showError(e)}}
const app=el('app');if(app){new MutationObserver(()=>{if(!app.hidden&&!el('accountsDashboard'))start()}).observe(app,{attributes:true,attributeFilter:['hidden']});if(!app.hidden)start()}
